function validate([s]) {
  if (typeof s !== 'string' || s.length !== 5) return 's must have exactly 5 characters.';
  if (s[2] !== ':') return 'The middle character s[2] must be ":".';
  for (const i of [0, 1, 3, 4]) if (!/^[0-9?]$/.test(s[i])) return 'Every character other than s[2] must be a digit or "?".';
  for (let h = 0; h < 12; h++) {
    for (let m = 0; m < 60; m++) {
      const t = String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
      if ([0, 1, 3, 4].every(i => s[i] === '?' || s[i] === t[i])) return null;
    }
  }
  return 'No time from 00:00 to 11:59 can be formed from s.';
}

