function findLatestTime(s) {
  for (let hour = 11; hour >= 0; hour--) {
    for (let minute = 59; minute >= 0; minute--) {
      const time = String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0');
      let matches = true;
      for (let i = 0; i < 5; i++) {
        if (s[i] !== '?' && s[i] !== time[i]) {
          matches = false;
          break;
        }
      }
      if (matches) {
        return time;
      }
    }
  }
  return '';
}

