function findLatestTime(s) {
  // Try every way to fill the '?' marks and keep the largest valid string.
  let best = null;
  const chars = s.split('');
  const fill = (i) => {
    if (i === chars.length) {
      const text = chars.join('');
      const hh = Number(text.slice(0, 2));
      const mm = Number(text.slice(3, 5));
      if (hh <= 11 && mm <= 59 && (best === null || text > best)) best = text;
      return;
    }
    if (chars[i] !== '?') return fill(i + 1);
    for (let d = 0; d <= 9; d++) {
      chars[i] = String(d);
      fill(i + 1);
    }
    chars[i] = '?';
  };
  fill(0);
  return best;
}

