function generate(rand, size) {
  // Every valid input is a valid time with some digits hidden, so hide digits of a random valid time.
  const hide = size === 'large' ? 0.6 : 0.4;
  const hour = Math.floor(rand() * 12);
  const minute = Math.floor(rand() * 60);
  const chars = (String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0')).split('');
  for (const i of [0, 1, 3, 4]) if (rand() < hide) chars[i] = '?';
  return [chars.join('')];
}
